/// Classify a Senzing error code. Unknown codes fall back to the base category.
pub fn classify(code: i32) -> SzErrorCategory {
    match CODES.binary_search_by_key(&code, |&(c, _)| c) {
        Ok(i) => CODES[i].1,
        Err(_) => SzErrorCategory::Base,
    }
}
